import{_ as o,o as r,c as t,a5 as a}from"./chunks/framework.DvE3tBec.js";const b=JSON.parse('{"title":"IEEE IGARRS 2021 HD-3: Hands-on openEO: access cloud platforms using your preferred programming language","description":"","frontmatter":{},"headers":[],"relativePath":"events/igarrs2021.md","filePath":"events/igarrs2021.md","lastUpdated":1625818606000}'),n={name:"events/igarrs2021.md"};function i(s,e,p,l,h,c){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="ieee-igarrs-2021-hd-3-hands-on-openeo-access-cloud-platforms-using-your-preferred-programming-language" tabindex="-1">IEEE IGARRS 2021 HD-3: Hands-on openEO: access cloud platforms using your preferred programming language <a class="header-anchor" href="#ieee-igarrs-2021-hd-3-hands-on-openeo-access-cloud-platforms-using-your-preferred-programming-language" aria-label="Permalink to &quot;IEEE IGARRS 2021 HD-3: Hands-on openEO: access cloud platforms using your preferred programming language&quot;">​</a></h1><p>This page contains the agenda, and links to used material for the IEEE IGARRS 2021 openEO tutorial.</p><p>Details: <a href="https://igarss2021.com/tutorials.php#tut9" target="_blank" rel="noreferrer">https://igarss2021.com/tutorials.php#tut9</a></p><h2 id="agenda" tabindex="-1">Agenda <a class="header-anchor" href="#agenda" aria-label="Permalink to &quot;Agenda&quot;">​</a></h2><ul><li>14:00-14:20: Introduction to openEO (Pieter Kempeneers - JRC)</li><li>14:20-14:30: Q&amp;A</li><li>14:30-15:30: Python client (VITO) (Jeroen Dries - VITO)</li><li>15:30-16:15: R client (WUR) (Dainius Masiliunas - WUR)</li><li>16:15-16:30: Break</li><li>16:30-16:45: openEO UIs (Jeroen Dries - VITO)</li><li>16:45-17:15: Use case demo (Jeroen Dries - VITO)</li><li>17:15-18:00: Q&amp;A</li></ul><h2 id="python-client" tabindex="-1">Python client <a class="header-anchor" href="#python-client" aria-label="Permalink to &quot;Python client&quot;">​</a></h2><h3 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h3><p>For participants interested in trying thing out, try logging into Terrascope openEO backend:</p><p><a href="https://docs.terrascope.be/#/Developers/WebServices/OpenEO/OpenEO" target="_blank" rel="noreferrer">https://docs.terrascope.be/#/Developers/WebServices/OpenEO/OpenEO</a></p><p>Jupyter notebooks with the openEO Python client installed: <a href="https://notebooks.terrascope.be" target="_blank" rel="noreferrer">https://notebooks.terrascope.be</a></p><p>This jupyter environment also has the notebook samples in this git repository already available:</p><p><a href="https://github.com/VITObelgium/notebook-samples" target="_blank" rel="noreferrer">https://github.com/VITObelgium/notebook-samples</a></p><p>Otherwise, git can be used to check out the notebooks, or simply download the &#39;ipynb&#39; file.</p><p>Use &#39;edugain and social accounts&#39; login to avoid having to register at Terrascope, you may still be required to fill in a form.</p><h3 id="openeo-in-python-intro" tabindex="-1">openEO in Python intro <a class="header-anchor" href="#openeo-in-python-intro" aria-label="Permalink to &quot;openEO in Python intro&quot;">​</a></h3><p>General Python documentation:</p><p><a href="https://open-eo.github.io/openeo-python-client/" target="_blank" rel="noreferrer">https://open-eo.github.io/openeo-python-client/</a></p><p>Basics:</p><p><a href="https://github.com/Open-EO/openeo-python-client/blob/master/examples/notebooks/openeo-terrascope-webinar.ipynb" target="_blank" rel="noreferrer">https://github.com/Open-EO/openeo-python-client/blob/master/examples/notebooks/openeo-terrascope-webinar.ipynb</a></p><p>More advanced:</p><p><a href="https://github.com/VITObelgium/notebook-samples/blob/master/tools/openEO/openeo-showcase.ipynb" target="_blank" rel="noreferrer">https://github.com/VITObelgium/notebook-samples/blob/master/tools/openEO/openeo-showcase.ipynb</a></p><h2 id="r-client" tabindex="-1">R client <a class="header-anchor" href="#r-client" aria-label="Permalink to &quot;R client&quot;">​</a></h2><p><a href="https://openeo.org/documentation/1.0/r/" target="_blank" rel="noreferrer">https://openeo.org/documentation/1.0/r/</a></p><p>Demonstration notebook:</p><p><a href="https://github.com/VITObelgium/notebook-samples/blob/master/tools/openEO/openeo-r-client.ipynb" target="_blank" rel="noreferrer">https://github.com/VITObelgium/notebook-samples/blob/master/tools/openEO/openeo-r-client.ipynb</a></p><h2 id="openeo-user-interfaces" tabindex="-1">openEO user interfaces <a class="header-anchor" href="#openeo-user-interfaces" aria-label="Permalink to &quot;openEO user interfaces&quot;">​</a></h2><p><a href="https://hub.openeo.org" target="_blank" rel="noreferrer">https://hub.openeo.org</a></p><p><a href="https://editor.openeo.org" target="_blank" rel="noreferrer">https://editor.openeo.org</a></p><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><p>Using predefined &#39;higher level&#39; services:</p><p><a href="https://github.com/VITObelgium/notebook-samples/blob/master/Terrascope/Beginner/OpenEO_CropCalendarService.ipynb" target="_blank" rel="noreferrer">https://github.com/VITObelgium/notebook-samples/blob/master/Terrascope/Beginner/OpenEO_CropCalendarService.ipynb</a></p><p>Creating &#39;higher level&#39; services:</p><p><a href="https://open-eo.github.io/openeo-python-client/udp.html#building-and-storing-user-defined-process" target="_blank" rel="noreferrer">https://open-eo.github.io/openeo-python-client/udp.html#building-and-storing-user-defined-process</a></p>',33)])])}const u=o(n,[["render",i]]);export{b as __pageData,u as default};
